# Writes the hedra command files of the jeweller's bench and the game pieces, and their textures:
#   bench.txt     the bench top (planks, textures/planks.png), 9 x 6.4 m, top at world y -0.04
#   tray.txt      the velvet tray: a 7 x 7 checker of 0.5 m cells (textures/velvet.png) at y 0, a wood
#                 frame with brass corners
#   drum.txt      the gem drum: the six gem cuts on one ring round the X axis (radius R_DRUM), one
#                 bone per board cell; the game turns the needed cut to the top, the other five stay
#                 under the velvet (art/assets.md, "Bones")
#   band.txt      the baguette mark (a dark rail with two gold tips), laid across a gem
#   claws.txt     the cluster mark (four gold claws at a gem's corners)
#   candle.txt    a candle in a brass dish; flame.txt its flame (a game bone, flickered by the game)
#   mandrel.txt   a ring mandrel with a gold ring on it
#   tweezers.txt  jeweller's tweezers
#   card.txt      the order card the HUD writes on
# Run from models/env: /usr/bin/python3 make_env.py
# Up Z, front -Y (hedra); world (glTF) = (x, z, -y) of hedra. Colours exact Galaxy Flame.
import os
from PIL import Image

HEX = {"teal": "699fad", "blue": "3a708e", "slate": "2b454f", "black": "111215", "pine": "151d1a",
       "deep": "1d3230", "moss": "314e3f", "olive": "4f5d42", "sage": "9a9f87", "cream": "ede6cb",
       "gold": "f5d893", "amber": "e8b26f", "tan": "b6834c", "brown": "704d2b", "umber": "40231e",
       "night": "151015"}


def rgb(n):
    h = HEX[n]
    return tuple(int(h[i:i + 2], 16) for i in (0, 2, 4))


def col(n):
    r, g, b = (c / 255 for c in rgb(n))
    return f"--base-color {r:.4f} {g:.4f} {b:.4f}"


CELL = 0.5          # board cell (m); the game's CELL
N = 7               # 7 x 7 board centred on the origin
R_DRUM = 0.78       # the drum ring's radius: a gem's base sits R_DRUM above the drum's axis
HALF = CELL * N / 2  # 1.75
FRAME = 0.2         # tray frame width
BENCH_Y = -0.04     # bench top (world y)
FRAME_Y = 0.07      # frame top

files = {}
os.makedirs("textures", exist_ok=True)

# ---------------------------------------------------------------- textures
# planks along x: 0.5 m planks, 4 texels of 0.125 m each: grain rows and a dark seam
W, H = 72, 52
im = Image.new("RGBA", (W, H))
for y in range(H):
    for x in range(W):
        plank = y // 4
        off = (plank * 23) % 31
        c = "umber"
        if y % 4 == 3:
            c = "night"                            # seam
        elif y % 4 == 1 and ((x + off) // 6) % 5 == 0:
            c = "brown"                            # grain streak
        elif (x + off) % 31 == 0:
            c = "night"                            # butt joint
        im.putpixel((x, y), rgb(c) + (255,))
im.save("textures/planks.png")

# velvet: 7 x 7 cells, each 4 x 4 texels (0.125 m): a quiet checker of two velvet steps
im = Image.new("RGBA", (N * 4, N * 4))
for y in range(N * 4):
    for x in range(N * 4):
        c = "deep" if ((x // 4) + (y // 4)) % 2 == 0 else "pine"
        im.putpixel((x, y), rgb(c) + (255,))
im.save("textures/velvet.png")

# ---------------------------------------------------------------- bench
files["bench"] = f"""# Bench: the jeweller's bench top, 9 x 6.4 m of dark planks (textures/planks.png), top at world
# y {BENCH_Y}. Only the top face: the bench is seen from above and everything below it is hidden.
# Generated by make_env.py. Up Z, front -Y.
new
material new Planks --base-color 1 1 1 --no-slot
material texture Planks base-color textures/planks.png
add mesh cube --name Bench --size 1 --location 0.1 0.2 {BENCH_Y - 0.1}
scale 9 6.4 0.2
apply --scale
material assign Planks
mode edit
select face where "normal.z < 0.9"
delete only-faces
select all
uv project-from-view top --scale-to-bounds
mode object
shade flat
export bench.glb
"""

# ---------------------------------------------------------------- tray
o = HALF + FRAME
bars = []
for name, cx, cy, sx, sy in (("BarN", 0, HALF + FRAME / 2, 2 * o, FRAME), ("BarS", 0, -(HALF + FRAME / 2), 2 * o, FRAME),
                             ("BarW", -(HALF + FRAME / 2), 0, FRAME, 2 * HALF), ("BarE", HALF + FRAME / 2, 0, FRAME, 2 * HALF)):
    hgt = FRAME_Y - BENCH_Y
    bars.append(f"""add mesh cube --name {name} --size 1 --location {cx:.3f} {cy:.3f} {(FRAME_Y + BENCH_Y) / 2:.3f}
scale {sx:.3f} {sy:.3f} {hgt:.3f}
apply --scale
mode edit
select face where "normal.z < -0.9"
delete only-faces
mode object""")
corners = []
for i, (sx, sy) in enumerate(((-1, -1), (1, -1), (-1, 1), (1, 1))):
    corners.append(f"add mesh cube --name Corner{i} --size 1 --location {sx * (HALF + FRAME / 2):.3f} {sy * (HALF + FRAME / 2):.3f} {FRAME_Y + 0.02:.3f}\n"
                   f"scale {FRAME + 0.04:.3f} {FRAME + 0.04:.3f} 0.06\napply --scale\nmode edit\nselect face where \"normal.z < -0.9\"\ndelete only-faces\nmode object")
files["tray"] = f"""# Tray: the velvet board, {N} x {N} cells of {CELL} m (textures/velvet.png: a checker of two velvet
# steps), top at world y 0; a wood frame {FRAME} m wide rising to y {FRAME_Y}, brass caps on its corners.
# Generated by make_env.py. Up Z, front -Y.
new
material new Velvet --base-color 1 1 1 --no-slot
material texture Velvet base-color textures/velvet.png
material new Frame {col('brown')} --no-slot
material new Brass {col('tan')} --no-slot
add mesh cube --name Velvet --size 1 --location 0 0 -0.1
scale {2 * HALF:.3f} {2 * HALF:.3f} 0.2
apply --scale
material assign Velvet
mode edit
select face where "normal.z < 0.9"
delete only-faces
select all
uv project-from-view top --scale-to-bounds
mode object
""" + "\n".join(bars) + "\nselect BarN BarS BarW BarE\nmaterial assign Frame\n" + "\n".join(corners) + """
select Corner0 Corner1 Corner2 Corner3
material assign Brass
select BarN BarS BarW BarE Corner0 Corner1 Corner2 Corner3
active BarN
join
rename BarN Frame
select Velvet
shade flat
select Frame
shade flat
export tray.glb
"""

# ---------------------------------------------------------------- the gem cuts
# each built upright with its base on z = 0 (it sits on the velvet), then lifted R_DRUM and turned
# about X by 60 degrees per slot. Slots: 0 sapphire (round), 1 jade (square), 2 amber (trillion),
# 3 garnet (marquise), 4 pearl, 5 the brilliant (an eight-point star).
def gem(k):
    z = R_DRUM
    nm = f"G{k}"
    if k == 0:
        parts = [f"add mesh cylinder --name {nm}a --vertices 8 --radius 0.215 --depth 0.04 --location 0 0 {z + 0.02:.3f}",
                 f"add mesh cone --name {nm}b --vertices 8 --radius1 0.215 --radius2 0.115 --depth 0.10 --location 0 0 {z + 0.09:.3f}"]
        spin, mat = 22.5, "Sapphire"
    elif k == 1:
        parts = [f"add mesh cylinder --name {nm}a --vertices 4 --radius 0.27 --depth 0.05 --location 0 0 {z + 0.025:.3f}",
                 f"add mesh cone --name {nm}b --vertices 4 --radius1 0.27 --radius2 0.155 --depth 0.09 --location 0 0 {z + 0.095:.3f}"]
        spin, mat = 45, "Jade"
    elif k == 2:
        parts = [f"add mesh cylinder --name {nm}a --vertices 3 --radius 0.27 --depth 0.04 --location 0 -0.03 {z + 0.02:.3f}",
                 f"add mesh cone --name {nm}b --vertices 3 --radius1 0.27 --radius2 0.12 --depth 0.11 --location 0 -0.03 {z + 0.095:.3f}"]
        spin, mat = 90, "Amber"
    elif k == 3:
        parts = [f"add mesh cylinder --name {nm}a --vertices 6 --radius 0.25 --depth 0.04 --location 0 0 {z + 0.02:.3f}",
                 f"add mesh cone --name {nm}b --vertices 6 --radius1 0.25 --radius2 0.12 --depth 0.10 --location 0 0 {z + 0.09:.3f}"]
        spin, mat = 0, "Garnet"
    elif k == 4:
        parts = [f"add mesh uv-sphere --name {nm}a --segments 8 --rings 6 --radius 0.195 --location 0 0 {z + 0.02:.3f}"]
        spin, mat = 22.5, "Pearl"
    else:
        parts = [f"add mesh cone --name {nm}a --vertices 4 --radius1 0.25 --radius2 0 --depth 0.17 --location 0 0 {z + 0.085:.3f}",
                 f"add mesh cone --name {nm}b --vertices 4 --radius1 0.17 --radius2 0 --depth 0.15 --location 0 0 {z + 0.075:.3f} --rotation 0 0 45"]
        spin, mat = 0, "Star"
    names = [f"{nm}a"] + ([f"{nm}b"] if len(parts) > 1 else [])
    out = parts[:]
    if k == 5:
        out.append(f"select {nm}b\napply --rotation")
    out.append(f"select {' '.join(names)}\nset rotation 0 0 {spin}\napply --rotation")
    if k == 3:
        out.append(f"select {' '.join(names)}\nscale 1 0.62 1\napply --scale")
    out.append(f"select {' '.join(names)}\nmaterial assign {mat}")
    # faces under the base (the girdle's and crown's bottoms, the pearl's lower half) are never seen
    for n in names:
        out.append(f"select {n}\nactive {n}\napply --location\nmode edit\nselect face where \"pos.z < {z + 0.005:.3f} || normal.z < -0.9\"\ndelete only-faces\nmode object")
    if len(names) > 1:
        out.append(f"select {' '.join(names)}\nactive {names[0]}\njoin")
    out.append(f"rename {names[0]} {nm}\nselect {nm}\nactive {nm}\nset rotation {60 * k} 0 0\napply --rotation")
    return "\n".join(out)


files["drum"] = f"""# Drum: the six gem cuts on one ring round the X axis, R {R_DRUM} m out, 60 degrees apart: slot 0
# sapphire (round brilliant), 1 jade (square step cut), 2 amber (trillion), 3 garnet (marquise),
# 4 pearl, 5 the brilliant (an eight-point star, unlit). The drum's origin is its axis; baked once a
# board cell (pool `gem`), the game turns the cut it needs to the top and the other five stay under
# the velvet and the bench. Generated by make_env.py. Up Z, front -Y.
new
material new Sapphire {col('blue')} --no-slot
material new Jade {col('olive')} --no-slot
material new Amber {col('amber')} --no-slot
material new Garnet {col('brown')} --no-slot
material new Pearl {col('cream')} --no-slot
material new Star {col('gold')} --no-slot
""" + "\n".join(gem(k) for k in range(6)) + """
select G0 G1 G2 G3 G4 G5
active G0
join
rename G0 Drum
shade flat
export drum.glb
"""

# ---------------------------------------------------------------- special marks
files["band"] = """# Band: the baguette mark, a dark rail 0.5 m long laid across a gem (along x) with a gold tip at
# each end on the velvet. Origin at its bottom centre. Generated by make_env.py. Up Z, front -Y.
new
material new Rail """ + col('black') + """ --no-slot
material new Tip """ + col('gold') + """ --no-slot
add mesh cube --name Rail --size 1 --location 0 0 0.03
scale 0.52 0.085 0.05
apply --scale
material assign Rail
mode edit
select face where "normal.z < -0.9"
delete only-faces
mode object
add mesh cone --name TipE --vertices 4 --radius1 0.085 --radius2 0 --depth 0.09 --location 0.31 0 0.045
material assign Tip
add mesh cone --name TipW --vertices 4 --radius1 0.085 --radius2 0 --depth 0.09 --location -0.31 0 0.045
material assign Tip
select Rail TipE TipW
active Rail
join
rename Rail Band
shade flat
export band.glb
"""

claws = []
for i, (sx, sy) in enumerate(((-1, -1), (1, -1), (-1, 1), (1, 1))):
    claws.append(f"add mesh cone --name C{i} --vertices 4 --radius1 0.08 --radius2 0 --depth 0.15 --location {sx * 0.19:.3f} {sy * 0.19:.3f} 0.075 --rotation 0 0 45\napply --rotation\nmaterial assign Claw")
files["claws"] = """# Claws: the cluster mark, four gold claws at a gem's corners. Origin at the gem's base centre.
# Generated by make_env.py. Up Z, front -Y.
new
material new Claw """ + col('gold') + """ --no-slot
""" + "\n".join(claws) + """
select C0 C1 C2 C3
active C0
join
rename C0 Claws
shade flat
export claws.glb
"""

# ---------------------------------------------------------------- props
files["candle"] = """# Candle: a brass dish 0.6 m across with a cup, a wax candle 0.5 m tall (top at 0.66). Origin on the
# bench under its centre. Generated by make_env.py. Up Z, front -Y.
new
material new Brass """ + col('tan') + """ --no-slot
material new Wax """ + col('cream') + """ --no-slot
add mesh cylinder --name Dish --vertices 12 --radius 0.3 --depth 0.05 --location 0 0 0.025
add mesh cylinder --name Cup --vertices 8 --radius 0.155 --depth 0.11 --location 0 0 0.105
add mesh torus --name Loop --major-segments 8 --minor-segments 4 --major-radius 0.09 --minor-radius 0.035 --location 0.36 0 0.05
select Dish Cup Loop
material assign Brass
add mesh cylinder --name Wax --vertices 8 --radius 0.12 --depth 0.5 --location 0 0 0.41 --rotation 0 0 22.5
apply --rotation
material assign Wax
add mesh cube --name Drip --size 1 --location 0.1 -0.06 0.55
scale 0.06 0.06 0.2
apply --scale
material assign Wax
select Dish
active Dish
mode edit
select face where "normal.z < -0.9"
delete only-faces
mode object
select Cup
active Cup
mode edit
select face where "normal.z < -0.9"
delete only-faces
mode object
select Wax
active Wax
mode edit
select face where "normal.z < -0.9"
delete only-faces
mode object
select Dish Cup Loop Wax Drip
active Dish
join
rename Dish Candle
shade flat
export candle.glb
"""

files["flame"] = """# Flame: a teardrop of light 0.28 m tall over the wick (unlit). Origin at its base. Generated by
# make_env.py. Up Z, front -Y.
new
material new Flame """ + col('gold') + """ --no-slot
material new Core """ + col('cream') + """ --no-slot
add mesh ico-sphere --name Bulb --subdivisions 1 --radius 0.075 --location 0 0 0.075
add mesh cone --name Tip --vertices 6 --radius1 0.065 --radius2 0 --depth 0.19 --location 0 0 0.18
select Bulb Tip
material assign Flame
add mesh ico-sphere --name Heart --subdivisions 1 --radius 0.045 --location 0 -0.045 0.07
material assign Core
select Bulb Tip Heart
active Bulb
join
rename Bulb Flame
shade flat
export flame.glb
"""

files["mandrel"] = """# Mandrel: a steel ring mandrel 0.72 m long on a wooden grip, lying along x, a gold ring on it.
# Origin on the bench under the grip end. Generated by make_env.py. Up Z, front -Y.
new
material new Steel """ + col('teal') + """ --no-slot
material new Grip """ + col('brown') + """ --no-slot
material new Gold """ + col('amber') + """ --no-slot
add mesh cone --name Taper --vertices 8 --radius1 0.1 --radius2 0.04 --depth 0.72 --location 0.66 0 0.1 --rotation 0 90 0
apply --rotation
material assign Steel
add mesh cylinder --name Grip --vertices 8 --radius 0.08 --depth 0.3 --location 0.15 0 0.08 --rotation 0 90 0
apply --rotation
material assign Grip
add mesh torus --name Ring --major-segments 10 --minor-segments 4 --major-radius 0.085 --minor-radius 0.04 --location 0.62 0 0.1 --rotation 0 90 0
apply --rotation
material assign Gold
select Taper Grip Ring
active Taper
join
rename Taper Mandrel
shade flat
export mandrel.glb
"""

files["tweezers"] = """# Tweezers: two steel prongs 0.95 m long joined at one end, opening by 0.12 m at the tips, lying on
# the bench along x. Origin at the joint. Generated by make_env.py. Up Z, front -Y.
new
material new Steel """ + col('teal') + """ --no-slot
add mesh cube --name ProngA --size 1 --location 0.47 0.035 0.03
scale 0.95 0.07 0.05
apply --scale
set rotation 0 0 3.6
apply --rotation
add mesh cube --name ProngB --size 1 --location 0.47 -0.035 0.03
scale 0.95 0.07 0.05
apply --scale
set rotation 0 0 -3.6
apply --rotation
add mesh cube --name Joint --size 1 --location 0.02 0 0.035
scale 0.12 0.14 0.07
apply --scale
select ProngA ProngB Joint
material assign Steel
active ProngA
join
rename ProngA Tweezers
shade flat
export tweezers.glb
"""

files["card"] = """# Card: the order card the HUD writes on, 1.4 x 3.5 m of cream paper lying on the bench (top at
# 0.07 above it: thinner, the bench's splats poke through). Origin under its centre. Generated by make_env.py. Up Z, front -Y.
new
material new Paper """ + col('cream') + """ --no-slot
add mesh cube --name Card --size 1 --location 0 0 0.035
scale 1.4 3.5 0.07
apply --scale
material assign Paper
mode edit
select face where "normal.z < -0.9"
delete only-faces
mode object
shade flat
export card.glb
"""

for name, text in files.items():
    with open(f"{name}.txt", "w") as f:
        f.write(text)
print("wrote", ", ".join(f"{n}.txt" for n in files), "and textures/planks.png, velvet.png")
